(302, 'CUST-A002', '东莞精密模具制造有限公司', '陈经理', '0769-8888-2002', 'chen.jl@jingmi-mold.com', '东莞市长安镇振安路 168 号'),
(303, 'CUST-A003', '苏州微创医疗器械有限公司', '王主任', '0512-8888-3003', 'wang.zr@weichuang-med.com', '苏州市工业园区星湖街 328 号创意产业园'),
