INSERT IGNORE INTO complaints (id, complaint_no, customer_id, severity, subject, description, status, five_w2h_json, assigned_to, due_date, acknowledged_at, closed_at, created_by) VALUES
(301, 'CMP-2026-001', 301, 'critical', '智能传感器成品 IP67 防水测试不合格', '2026-07 批次交付的 200 套温湿度传感器 D400，客户上线组装后发现 8 套外壳渗水，防水测试不合格。客户要求 48 小时内提供 8D 报告。', 'in_progress', '{"what":"传感器外壳渗水","where":"客户深圳工厂 SMT 产线","when":"2026-07-25 发现","who":"华芯科技质量部刘总监","why":"IP67 防水测试不合格","how_many":"8/200 (4%)","how":"气密性测试 30s 内压力下降超标"}', 9, '2026-08-08', '2026-07-25 14:30:00', NULL, 3),
(302, 'CMP-2026-002', 302, 'major', '主控 PCB 板 BGA 芯片信号异常', '客户在 PCB-A100 主板贴片后功能测试中，发现 3 块板 BGA 芯片信号传输不稳定，X-Ray 检测确认焊点虚焊。已暂停该批次上线。', 'in_progress', '{"what":"BGA 焊点虚焊导致信号异常","where":"东莞精密模具 SMT 车间","when":"2026-07-28 09:00","who":"精密模具品质课陈工","why":"回流焊炉温曲线偏移","how_many":"3 pcs / 抽检 50 pcs","how_many_pct":"6%"}', 8, '2026-08-11', '2026-07-28 10:00:00', NULL, 2),
(303, 'CMP-2026-003', 303, 'minor', '防水连接器外观划伤影响客户装配', '苏州微创接收的 500 套防水连接器 F600 中，发现 15 套外壳表面有轻微划伤，虽不影响功能但影响客户产品外观品质。客户为医疗器械行业，对外观要求严格。', 'completed', '{"what":"连接器外壳表面划伤","where":"苏州微创来料检验","when":"2026-06-15","who":"微创 IQC 王检验员","why":"包装防护不足，运输中碰撞","how_many":"15/500 (3%)","how":"目视检查发现划痕，深度约 0.1-0.3mm"}', 10, '2026-07-15', '2026-06-16 09:00:00', '2026-07-10 16:00:00', 5),
(304, 'CMP-2026-004', 304, 'critical', 'LDO 电源管理芯片输出电压偏差超标', '上海汽车零部件收到的 IC-E500（LDO 5V）批量上线后，客户测试发现输出电压实际值 4.82V~4.88V，标准 5.0V±2%。部分敏感电路工作异常，已紧急停线。', 'closed', '{"what":"LDO 输出电压偏低 (4.82-4.88V vs 5.0V)","where":"上海汽车零部件生产线","when":"2026-05-20","who":"汽车零部件质量部张工","why":"IC 批次性能偏差","how_many":"200 pcs 中 35 pcs 超标 (17.5%)","how":"万用表实测输出电压"}', 12, '2026-06-20', '2026-05-21 08:00:00', '2026-06-18 17:00:00', 2),
(305, 'CMP-2026-005', 305, 'minor', 'LED 指示灯组件亮度不均匀', '杭州智能物联收到的 LED-G700 指示灯组件（1000 pcs），抽检发现 20 颗 LED 亮度明显偏低，肉眼可分辨色差。不影响基本功能但影响产品档次感。', 'closed', '{"what":"LED 亮度不均匀，20 颗明显偏低","where":"杭州智能物联成品组装线","when":"2026-06-05","who":"智能物联品质部赵检验","why":"LED 芯片批次间差异","how_many":"20/1000 (2%)","how":"在标准光源箱下对比检查"}', 4, '2026-06-25', '2026-06-06 10:00:00', '2026-06-22 16:00:00', 6),
(306, 'CMP-2026-006', 301, 'major', '电机驱动装配组件 C300 销轴尺寸超差', '华芯科技反馈装配组件 C300 的 3 个定位销轴直径偏大（实测 5.03mm，标准 5.00±0.02mm），导致客户产线装配困难，强行压入造成壳体开裂。', 'in_progress', '{"what":"定位销轴直径超差 (5.03mm vs 5.00±0.02mm)","where":"华芯科技装配车间","when":"2026-07-15","who":"华芯科技工艺部","why":"CNC 加工尺寸控制不当","how_many":"10 pcs 中 4 pcs 超差","how":"千分尺测量销轴外径"}', 7, '2026-08-15', '2026-07-16 09:00:00', NULL, 2),
(307, 'CMP-2026-007', 302, 'major', '铝合金外壳喷涂批次间色差明显', '东莞精密模具反馈批次 302 的铝合金外壳 B200 与样品色差明显（ΔE=3.2），同批次内也有色差（ΔE=1.8~3.2）。客户要求对 500 pcs 全检分选。', 'closed', '{"what":"铝合金外壳喷涂色差 ΔE>2.5","where":"精密模具喷漆车间→客户组装线","when":"2026-04-10","who":"精密模具品质课","why":"油漆批次更换未重新标定","how_many":"500 pcs 中 68 pcs ΔE>2.5 (13.6%)","how":"色差仪测量 ΔE 值"}', 8, '2026-05-10', '2026-04-11 08:30:00', '2026-05-08 17:00:00', 3),
(308, 'CMP-2026-008', 305, 'critical', 'PCB 板电解电容漏焊导致功能失效', '杭州智能物联在批量生产中使用 I900 陶瓷电容的 PCB 板出现 5 例功能失效，拆机检测发现 2 颗电容焊点完全虚焊（漏焊）。已识别为 I900 电容引脚可焊性不良。', 'in_progress', '{"what":"陶瓷电容焊点虚焊/漏焊","where":"智能物联 SMT 产线","when":"2026-07-30","who":"智能物联 PE 赵工","why":"电容引脚可焊性不良","how_many":"5 例失效 / 批量 300 pcs","how":"X-Ray 检测 + 拆机目视确认"}', 11, '2026-08-13', '2026-07-31 09:00:00', NULL, 5);
INSERT IGNORE INTO d8_reports (id, complaint_id, status, d0_description, d1_team, d2_description, d3_measures, d4_analysis_method, d4_content, d4_root_cause, d5_actions, d6_verification, d7_preventive, d8_thanks, current_discipline, completed_at) VALUES (401, 301, 'in_progress', '2026-07 批次 200 套温湿度传感器 D400 交付后，客户上线组装发现 8 套 IP67 防水测试不合格，渗水率 4%。', '["张三（质量工程师，组长）","李四（工艺工程师）","王五（生产主管）"]', '5W2H 分析：产品=传感器 D400，问题=外壳渗水，位置=客户深圳工厂 SMT 线，时间=2026-07-25，发现者=刘总监', '[{"item":"隔离批次 306 库存，禁止出货","owner":"王五","date":"2026-07-25"},{"item":"对客户已收 50 套进行 100% 气密性复检","owner":"张三","date":"2026-07-26"}]', 'fishbone', '{"人":"操作员密封胶涂抹不均匀","机":"自动打胶机压力设定偏差","料":"O 型圈批次硬度偏高","法":"密封面清洁标准不明确"}', '自动打胶机压力设定偏差导致密封胶涂抹不均匀，加之 O 型圈批次硬度偏高，双重因素导致密封失效', '[{"action":"重新标定打胶机压力参数（从 0.3MPa 调整为 0.25MPa）","owner":"李四","due":"2026-08-02","status":"completed"},{"action":"更换 O 型圈供应商，采用更宽硬度范围的材料","owner":"张三","due":"2026-08-10","status":"in_progress"},{"action":"制定密封面清洁 SOP 并培训操作员","owner":"王五","due":"2026-08-05","status":"pending"}]', '[{"verification":"打胶机参数调整后连续 3 批次气密性测试合格率 100%","conclusion":"有效","date":"2026-08-03"}]', '[{"preventive":"将打胶机压力纳入月度点检项目，偏差 >5% 自动报警","owner":"李四"},{"preventive":"建立 O 型圈来料硬度抽检标准（每批次 5 pcs）","owner":"张三"}]', NULL, 5, NULL), (402, 302, 'in_progress', 'PCB-A100 主控板贴片后功能测试中 3 块 BGA 芯片信号传输不稳定，X-Ray 检测确认焊点虚焊。', '["赵六（质量经理）","李四（工艺工程师）","孙七（SMT 主管）"]', '5W2H：产品=PCB-A100 主板，问题=BGA 虚焊，位置=SMT 车间，时间=2026-07-28，数量=3/50', '[{"item":"批次 301 全检，X-Ray 100% 检测 BGA 焊点","owner":"孙七"},{"item":"不合格品返工，重新回流焊接","owner":"李四"}]', 'five_whys', '["为什么虚焊？锡膏润湿不充分","为什么润湿不充分？回流焊实际温度偏低","为什么温度偏低？热电偶校准过期 3 个月","为什么校准过期？校准周期管理缺失","为什么管理缺失？没有建立校准计划台账"]', '回流焊炉温校准周期管理缺失，热电偶过期导致实际炉温低于设定值 15°C，BGA 焊点润湿不充分', '[{"action":"立即更换热电偶并重新校准炉温曲线","owner":"李四","due":"2026-08-01","status":"completed"},{"action":"建立炉温校准 SOP，每月校准一次","owner":"赵六","due":"2026-08-10","status":"in_progress"},{"action":"批次 301 返工后 X-Ray 复检","owner":"孙七","due":"2026-08-03","status":"completed"}]', '[{"verification":"返工后连续 5 批次 X-Ray 检测合格率 100%，功能测试 PASS","conclusion":"有效","date":"2026-08-05"}]', '[{"preventive":"导入炉温自动监控系统，异常自动报警","owner":"李四","due":"2026-08-30"},{"preventive":"将 SMT 炉温校准纳入质量月报","owner":"赵六","due":"2026-08-15"}]', NULL, 6, NULL), (403, 303, 'closed', '500 套防水连接器 F600 交付客户，15 套（3%）外壳表面有轻微划伤，深度 0.1~0.3mm。', '["周八（质量工程师）","吴九（仓储主管）"]', '5W2H：产品=F600 连接器，问题=外壳划伤，位置=客户来料检验，数量=15/500', '[{"item":"与客户协商，划伤品全检挑选或使用","owner":"周八"}]', 'five_whys', '["为什么划伤？运输中产品互相碰撞","为什么碰撞？内包装隔层不足","为什么隔层不足？包装设计未考虑堆叠场景","为什么设计不充分？包装验证试验不充分"]', '包装设计未覆盖实际运输堆叠场景，内包装隔层不足以防止产品间碰撞', '[{"action":"重新设计内包装，增加独立分隔格","owner":"周八","due":"2026-06-25","status":"completed"},{"action":"对划伤品与客户协商挑选使用","owner":"周八","due":"2026-06-20","status":"completed"}]', '[{"verification":"新包装设计通过 ISTA 3A 运输振动测试","conclusion":"有效","date":"2026-06-28"}]', '[{"preventive":"所有新产品包装设计必须通过 ISTA 3A 测试","owner":"周八"},{"preventive":"将包装验证纳入新产品开发 checklist"}]', '感谢质量部、仓储部和客户的积极配合，本次 8D 在 24 天内高效关闭，包装改善方案已推广至所有连接器产品线。', 8, '2026-07-10 16:00:00'), (404, 304, 'closed', 'IC-E500（LDO 5V）批量上线后输出电压 4.82~4.88V，标准 5.0V±2%，部分敏感电路工作异常。', '["王芳（质量经理）","郑十（采购经理）","李四（质量工程师）"]', '5W2H：产品=E500 LDO 5V，问题=输出电压偏低，位置=客户生产线，数量=35/200', '[{"item":"退货处理全部 200 pcs，紧急调用安全库存","owner":"郑十","date":"2026-05-22"}]', 'five_whys', '["为什么电压偏低？IC 批次性能偏差","为什么偏差？代工厂工艺波动","为什么工艺波动？代工厂更换封装测试厂","为什么更换厂未通知？供应商变更管理缺失"]', 'IC 代工厂未经通知更换封装测试厂，新工艺参数导致输出电压偏低', '[{"action":"向供应商发出 8D 报告，要求限期整改","owner":"王芳","due":"2026-06-05","status":"completed"},{"action":"退货换货，新批次 IQC 加严检测","owner":"郑十","due":"2026-06-10","status":"completed"},{"action":"更新 IQC 检验标准，增加输出电压全检","owner":"李四","due":"2026-06-15","status":"completed"}]', '[{"verification":"新到 500 pcs 输出电压全检 5.00±0.05V，合格率 100%","conclusion":"有效","date":"2026-06-18"}]', '[{"preventive":"将 IC 输出电压纳入供应商年度审核必查项","owner":"王芳"},{"preventive":"建立关键 IC 安全库存机制，最低 2 周用量"}]', '本次客诉从发现到关闭仅用 28 天，跨部门协作高效。建议将供应商变更管理纳入供应商准入培训。', 8, '2026-06-18 17:00:00'), (405, 305, 'closed', 'LED-G700 指示灯组件 1000 pcs 中 20 颗亮度偏低，肉眼可分辨色差。', '["陈工（质量工程师）","刘工（工艺工程师）"]', '5W2H：产品=G700 LED，问题=亮度不均，位置=客户组装线，数量=20/1000', '[{"item":"客户线上挑选使用，不良品退回","owner":"陈工"}]', 'fishbone', '{"人":"检验员目视标准不统一","机":"分光光度计未校准","料":"LED 芯片批次间光通量差异","法":"出厂检验仅测亮灯不测亮度一致性"}', 'LED 芯片批次间光通量差异较大，且出厂检验标准不完善，仅检查亮灯未检查亮度一致性', '[{"action":"更新出货检验标准，增加亮度一致性检测（分光光度计）","owner":"陈工","due":"2026-06-15","status":"completed"},{"action":"对退回的 20 pcs 与供应商协商换货","owner":"陈工","due":"2026-06-20","status":"completed"}]', '[{"verification":"新批次 500 pcs 亮度一致性检测全部合格，最大偏差 <5%","conclusion":"有效","date":"2026-06-22"}]', '[{"preventive":"LED 芯片纳入关键来料管控，每批次抽检光通量","owner":"陈工"},{"preventive":"建立 LED 芯片供应商光通量能力档案"}]', '本次改善推动了出货检验标准的升级，后续所有光电类产品将增加亮度一致性检测。', 8, '2026-06-22 16:00:00'), (406, 306, 'in_progress', '装配组件 C300 定位销轴直径 5.03mm，超差 0.03mm，导致客户装配困难、壳体开裂。', '["王芳（质量经理）","周工（工艺工程师）","陈工（生产主管）"]', '5W2H：产品=C300 装配组件，问题=销轴超差，位置=客户装配车间，数量=4/10', '[{"item":"隔离批次 308 库存，不合格品全检筛选","owner":"陈工","date":"2026-07-16"}]', 'five_whys', '["为什么超差？CNC 加工尺寸控制不当","为什么控制不当？刀具磨损未及时调整","为什么未调整？刀具寿命管理未执行","为什么未执行？CNC 机床刀具计数器未设定","为什么未设定？新设备导入时遗漏"]', 'CNC 新设备导入时未设定刀具寿命计数器，刀具磨损后未及时调整导致加工尺寸超差', NULL, NULL, NULL, NULL, 4, NULL), (407, 307, 'closed', '铝合金外壳 B200 批次 302 与样品色差明显（ΔE=3.2），500 pcs 中 68 pcs ΔE>2.5。', '["李四（质量工程师）","吴工（喷涂主管）"]', '5W2H：产品=B200 铝合金外壳，问题=喷涂色差，位置=客户组装线，数量=68/500', '[{"item":"隔离全部 500 pcs，客户全检分选","owner":"吴工","date":"2026-04-12"}]', 'fishbone', '{"人":"操作员未按时校准色差仪","机":"喷枪压力波动","料":"油漆批次更换","法":"喷涂厚度标准不统一"}', '油漆批次更换后未重新校准喷涂参数，导致色差超标', '[{"action":"重新标定喷涂设备压力参数","owner":"吴工","due":"2026-04-25","status":"completed"},{"action":"油漆批次更换时必须执行首件确认","owner":"李四","due":"2026-04-28","status":"completed"}]', '[{"verification":"连续 3 批色差 ΔE<1.5，全部合格","conclusion":"有效","date":"2026-05-08"}]', '[{"preventive":"引入色差自动在线检测系统","owner":"李四","due":"2026-06-01"}]', '本次色差问题推动了在线检测系统的引入，喷涂工艺控制水平显著提升。', 8, '2026-05-08 17:00:00'), (408, 308, 'in_progress', 'PCB 板使用 I900 陶瓷电容出现 5 例功能失效，拆机检测发现焊点虚焊/漏焊。', '["孙七（SMT 主管）","李四（工艺工程师）","周工（质量工程师）"]', '5W2H：产品=I900 陶瓷电容，问题=焊点虚焊，位置=智能物联 SMT 线，数量=5/300', '[{"item":"冻结批次 319 电容，暂停使用","owner":"周工","date":"2026-07-31"},{"item":"已生产 PCB 板全检 X-Ray","owner":"孙七","date":"2026-07-31"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, NULL);
